// Filter applies the EntityWhereInput filter on the EntityQuery builder.
func (i *EntityWhereInput) Filter(q *EntityQuery) (*EntityQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyEntityWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

