// Filter applies the OAuthPendingWhereInput filter on the OAuthPendingQuery builder.
func (i *OAuthPendingWhereInput) Filter(q *OAuthPendingQuery) (*OAuthPendingQuery, error) {
	if i == nil {
		return q, nil
	}
	p, err := i.P()
	if err != nil {
		if err == ErrEmptyOAuthPendingWhereInput {
			return q, nil
		}
		return nil, err
	}
	return q.Where(p), nil
}

